// tests/evaluation/review-integrity/fixtures/registry.js
// Regression corpus loader for Review Integrity (RI-01 through RI-04).
//
// Loads faithful fixture snapshots from JSON files generated by
// build-snapshots.mjs. Each snapshot contains the exact changed-file list
// and patches GitWire's reviewPR() would have received at the historical
// head, plus exact repository file contents needed for v2 retrieval.
//
// The corpus is a SEED CORPUS — every new material production review miss
// becomes a new case.

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const SNAPSHOTS_DIR = path.join(__dirname, "snapshots");

// Expected finding metadata for each broken fixture.
// These are the exact Codex findings from the historical review threads.
const EXPECTED_FINDINGS = {
  "RI-01": {
    severity: "P2",
    title: "Synchronize all Phase 0 status declarations",
    description:
      "This new status says Phase 0.0 is closed, but the primary README.md, " +
      "the frozen constitution at docs/constitution.md, and this specification's " +
      "own summary still say it is reopened with the scaffold pending. Readers " +
      "therefore receive contradictory build state depending on their entry point.",
    evidencePaths: ["README.md", "docs/constitution.md", "docs/phase-0-spec.md"],
  },
  "RI-02": {
    severity: "P2",
    title: "Add agent-replacement assertions to gate 0.5",
    description:
      "When gate 0.5 is implemented from the document declared authoritative, " +
      "this new exit requirement will not be enforced: docs/phase-0-spec.md " +
      "checks killing and reopening the whole process with intact state, but " +
      "never replaces or restarts an Agent independently or verifies preservation " +
      "of Host-owned execution identity. The gate can therefore pass without " +
      "proving the replaceable-Agent property that this roadmap explicitly makes " +
      "part of the 0.5 exit proof.",
    evidencePaths: ["docs/roadmap.md", "docs/phase-0-spec.md"],
  },
  "RI-03": {
    severity: "P1",
    title: "Activation URL missing /dashboard basePath",
    description:
      "The URL is constructed as baseUrl + '/intelligence' but next.config.ts " +
      "sets basePath: '/dashboard'. The correct URL is baseUrl + '/dashboard/intelligence'.",
    evidencePaths: ["packages/web/src/services/aiReviewService.js", "packages/web-dashboard/next.config.ts"],
  },
  "RI-04": {
    severity: "P2",
    title: "Unpaginated findCommentByMarker will duplicate comments on high-volume issues",
    description:
      "The broadened comment path now calls findCommentByMarker() for every " +
      "triaged issue, but that function fetches only one page of 100 comments " +
      "with no pagination. If the marker comment is beyond page 1, it returns " +
      "null and postMarkedComment creates a duplicate comment.",
    evidencePaths: ["packages/web/src/workers/triageWorker.js", "packages/web/src/lib/commentMarkers.js"],
  },
};

function loadSnapshot(caseId, variant) {
  const filename = `${caseId.toLowerCase().replace("-", "")}-${variant}.json`;
  const filepath = path.join(SNAPSHOTS_DIR, filename);
  if (!fs.existsSync(filepath)) {
    throw new Error(`Fixture snapshot not found: ${filename}. Run build-snapshots.mjs first.`);
  }
  const raw = JSON.parse(fs.readFileSync(filepath, "utf-8"));

  // Enrich with expected finding metadata
  if (variant === "broken" && EXPECTED_FINDINGS[caseId]) {
    raw.expectedFinding = EXPECTED_FINDINGS[caseId];
    raw.expectedVerdict = "never APPROVE";
  } else {
    raw.expectedFinding = null;
    raw.expectedVerdict = "eligible for APPROVE";
  }

  return raw;
}

// Preload all snapshots
const _fixtures = [];
for (const caseId of ["RI-01", "RI-02", "RI-03", "RI-04"]) {
  for (const variant of ["broken", "fixed"]) {
    _fixtures.push(loadSnapshot(caseId, variant));
  }
}

export const REGISTRY = Object.freeze(_fixtures);

export function getAllFixtures() {
  return REGISTRY;
}

export function getBrokenFixtures() {
  return REGISTRY.filter(f => f.variant === "broken");
}

export function getFixedFixtures() {
  return REGISTRY.filter(f => f.variant === "fixed");
}
